            return d2 - 0.8 * near + 0.2 * wall_term + (0.001 * (t % 2))

    best = None
    best_score = None
    for k, (dx, dy) in enumerate(moves):
        nx, ny = sx + dx, sy + dy
        if not in_bounds(nx, ny):
